#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

# Assistant de déploiement de plakar-ui (ticket 09), à lancer sur le Mac :
#   scripts/deploy-wizard.sh
# Il écrit .env à la racine du dépôt et vérifie le service depuis le PC. Les
# commandes pour Proxmox et pour le LXC sont affichées : tu les lances toi-même.
cd "$(dirname "$0")/.."

# ouvert HOTE PORT : le port accepte-t-il une connexion TCP ? (curl rend 7 sur
# un refus, 28 sur un délai dépassé ; tout autre code veut dire connecté.)
ouvert() {
  local rc=0
  curl -s -o /dev/null --connect-timeout 3 --max-time 5 "http://$1:$2/" || rc=$?
  [[ $rc -ne 7 && $rc -ne 28 ]]
}

# code_https URL : code HTTP de la page, vu depuis ce PC et son identité Tailscale.
code_https() {
  curl -s -o /dev/null -w '%{http_code}' --max-time 15 "$1" || true
}

# attendu "libellé" OK : affiche le résultat d'une vérification, et le garde
# dans le résumé final s'il a échoué.
attendu() {
  if [[ "$2" == ok ]]; then
    printf '  %s✓%s %s\n' "$GREEN" "$RESET" "$1"
  else
    warn "$1 : ÉCHEC"
    SKIPPED+=("vérification à reprendre : $1")
  fi
}

TOTAL_STAGES=13

banner "Déploiement de plakar-ui dans le LXC Docker"

# .env ne reçoit que les valeurs saisies ici : les réglages absents gardent leur
# défaut (documenté dans .env.example).

# ── 1 ──────────────────────────────────────────────────────────────────────
stage "Tailnet : MagicDNS, certificats HTTPS et nom du tailnet"
say "tailscale serve a besoin de MagicDNS et des certificats HTTPS du tailnet."
open_url "https://login.tailscale.com/admin/dns"
step "Vérifie que MagicDNS est activé (sinon : Enable MagicDNS)."
step "Plus bas, section HTTPS Certificates : clique Enable HTTPS si ce n'est pas fait."
step "En haut de la page, relève le Tailnet DNS name (par exemple tail1234.ts.net)."
current=$(_existing PLAKAR_UI_HOTE || true)
[[ -n "$current" ]] && note "Actuel : $current (Entrée le garde)."
ask TAILNET "Nom DNS du tailnet (sans plakar-ui devant) :"
[[ -z "$TAILNET" && -n "$current" ]] && TAILNET="${current#plakar-ui.}"
write_env PLAKAR_UI_HOTE "plakar-ui.${TAILNET#.}"
pause "Entrée pour continuer"

# ── 2 ──────────────────────────────────────────────────────────────────────
stage "Valeurs du service"
say "Les autres réglages (Seuil, intervalle, plage de ports…) gardent leur défaut ;"
say "ils se changent plus tard dans .env (voir les commentaires)."
ask PLAKAR_UI_UTILISATEURS "Ton identité Tailscale (email ; plusieurs : séparées par des virgules) :"
write_env PLAKAR_UI_UTILISATEURS "$PLAKAR_UI_UTILISATEURS"
ask UNRAID_IP "IP LAN d'Unraid (pour le nom unraid des Stores) :"
write_env UNRAID_IP "$UNRAID_IP"
ask PLAKAR_UI_APPDATA "Dossier des volumes sur le LXC (ex. /opt/appdata/plakar-ui) :"
write_env PLAKAR_UI_APPDATA "${PLAKAR_UI_APPDATA%/}"
note "TS_AUTHKEY reste inutilisée : le nœud se connectera par URL (étape 7)."
pause "Entrée pour continuer"

# ── 3 ──────────────────────────────────────────────────────────────────────
stage "Proxmox : autoriser /dev/net/tun dans le LXC"
say "Le sidecar tourne en mode TUN (le mode userspace contournait l'Accès)."
say "Le LXC doit donc voir /dev/net/tun."
ask CTID "ID du conteneur LXC (CTID) sur Proxmox :"
step "Sur l'hôte Proxmox, ajoute ces deux lignes à /etc/pve/lxc/${CTID}.conf :"
note "    lxc.cgroup2.devices.allow: c 10:200 rwm"
note "    lxc.mount.entry: /dev/net/tun dev/net/tun none bind,create=file"
step "Redémarre le conteneur : pct reboot ${CTID}"
step "Dans le LXC, vérifie : ls -l /dev/net/tun   (attendu : crw-rw-rw- … 10, 200)"
confirm "/dev/net/tun est visible dans le LXC ?" || SKIPPED+=("/dev/net/tun dans le LXC ${CTID}")

# ── 4 ──────────────────────────────────────────────────────────────────────
stage "Transfert vers le LXC"
say "Copie le dépôt sur le LXC, avec le fichier $ENV_FILE que cet assistant vient"
say "d'écrire (il contient tes réglages, pas de secret). Inutile d'envoyer .git ni .scratch."
note "Les commandes des étapes suivantes se lancent dans ce dossier, sur le LXC."
pause "Entrée une fois le dépôt et $ENV_FILE sur le LXC"

# ── 5 ──────────────────────────────────────────────────────────────────────
stage "Dossiers appdata"
say "Docker créerait les dossiers manquants en root, et plakar-ui (UID 1000) ne"
say "pourrait pas y écrire. Sur le LXC :"
note "    A=${PLAKAR_UI_APPDATA}"
note '    mkdir -p "$A"/{tailscale,serve,plakar-config,plakar-cache,state}'
note '    chown 1000:1000 "$A"/{serve,plakar-config,plakar-cache,state}'
note '    chmod 700 "$A/plakar-config"'
warn "plakar-config contiendra tes passphrases en clair : traite ce dossier comme sensible."
pause "Entrée une fois les dossiers prêts"

# ── 6 ──────────────────────────────────────────────────────────────────────
stage "Construction et démarrage"
say "Sur le LXC, dans le dossier du dépôt :"
note "    docker compose up -d --build"
say "La construction compile plakar v1.1.6 et lance le test de contrat avec lui :"
say "compte 3 à 5 minutes. Si le contrat échoue, l'image n'est pas créée."
step "Puis : docker compose ps   (attendu : tailscale et plakar-ui en running)"
confirm "Les deux conteneurs tournent ?" || SKIPPED+=("démarrage du compose")

# ── 7 ──────────────────────────────────────────────────────────────────────
stage "Connexion du nœud plakar-ui au tailnet"
say "Pas de clé d'authentification : le sidecar affiche une URL de connexion."
step "Sur le LXC : docker compose logs tailscale | grep login.tailscale.com/a/"
step "Ouvre cette URL sur le PC et connecte le nœud avec ton compte."
pause "Entrée une fois le nœud connecté"
open_url "https://login.tailscale.com/admin/machines"
step "Dans Machines, vérifie que le nœud s'appelle exactement plakar-ui."
note "S'il s'appelle plakar-ui-1 (nom déjà pris), PLAKAR_UI_HOTE ne correspond plus :"
note "renomme-le en plakar-ui (menu … > Edit machine name)."
step "Menu … du nœud > Disable key expiry, sinon il se déconnecte au bout de 180 jours."
confirm "Le nœud plakar-ui est là, sans expiration ?" || SKIPPED+=("nœud plakar-ui sur le tailnet")

# ── 8 ──────────────────────────────────────────────────────────────────────
stage "Tableau de bord depuis le PC"
say "Le premier accès HTTPS déclenche la création du certificat : il peut prendre"
say "une quinzaine de secondes."
code=$(code_https "https://${PLAKAR_UI_HOTE}/")
[[ "$code" == 200 ]] && r=ok || r=ko
attendu "https://${PLAKAR_UI_HOTE}/ répond 200 (reçu : ${code:-rien})" "$r"
open_url "https://${PLAKAR_UI_HOTE}/"
pause "Entrée pour continuer"

# ── 9 ──────────────────────────────────────────────────────────────────────
stage "Stores"
say "Dans le bloc Commande de Store du tableau de bord, ajoute tes Stores avec la"
say "syntaxe officielle, par exemple :"
note "    plakar store add arr http://unraid:9876 passphrase=…"
say "Après chaque ajout, le service lance un Relevé du nouveau Store."
step "Attends que chaque Store affiche son Dernier snapshot (et non Injoignable)."
step "Sur le LXC, vérifie les droits de la config : ls -l ${PLAKAR_UI_APPDATA}/plakar-config"
note "    attendu : -rw------- … stores.yml   (sinon : chmod 600 …/stores.yml)"
confirm "Chaque Store a un premier Relevé réussi, et stores.yml est en 600 ?" || SKIPPED+=("Stores et premier Relevé")

# ── 10 ─────────────────────────────────────────────────────────────────────
stage "Exploration"
step "Sur le tableau de bord, clique Explorer sur un Store."
step "Ouvre le lien affiché (https://${PLAKAR_UI_HOTE}:<port>/?plakar_token=…)."
step "L'interface de plakar doit afficher les snapshots du Store."
note "Laisse cette Exploration ouverte : l'étape suivante vérifie ses ports internes."
confirm "L'Exploration s'ouvre ?" || SKIPPED+=("Exploration depuis le PC")

# ── 11 ─────────────────────────────────────────────────────────────────────
stage "Restrictions réseau"
TS_IP=$(tailscale ip -4 plakar-ui 2>/dev/null || true)
if [[ -z "$TS_IP" ]]; then
  warn "IP Tailscale de plakar-ui introuvable (tailscale ip -4 plakar-ui) ; vérifications par nom."
  TS_IP="$PLAKAR_UI_HOTE"
fi
say "Depuis le tailnet ($TS_IP) : seuls 443 et la plage d'Exploration répondent."
ouvert "$TS_IP" 443 && r=ok || r=ko
attendu "tailnet : 443 ouvert" "$r"
for port in 8080 9400 9401 9420; do
  ouvert "$TS_IP" "$port" && r=ko || r=ok
  attendu "tailnet : $port fermé (pas de chemin hors de tailscale serve)" "$r"
done
ask LXC_IP "IP LAN du LXC (pour vérifier que rien n'y répond hors Tailscale) :"
for port in 443 8080 9300 9400; do
  ouvert "$LXC_IP" "$port" && r=ko || r=ok
  attendu "LAN : $LXC_IP:$port fermé" "$r"
done
pause "Entrée pour continuer"

# ── 12 ─────────────────────────────────────────────────────────────────────
stage "Politique du tailnet (défense en profondeur)"
say "Objectif : vers plakar-ui, n'autoriser que 443 et 9300-9320, pour tes seules identités."
open_url "https://login.tailscale.com/admin/acls/file"
step "Ajoute dans \"hosts\" :  \"plakar-ui\": \"${TS_IP}\""
step "Ajoute dans \"grants\" :"
note "    {\"src\": [\"${PLAKAR_UI_UTILISATEURS%%,*}\"], \"dst\": [\"plakar-ui\"],"
note "     \"ip\": [\"tcp:443\", \"tcp:9300-9320\"]}"
warn "Si ta politique garde la règle par défaut (src * vers dst *), elle ouvre déjà tout :"
warn "la règle ci-dessus ne restreint rien tant que celle-là n'est pas remplacée par des"
warn "règles explicites. Cela touche tout ton tailnet : à toi de juger."
if confirm "Politique enregistrée ? (non : étape remise à plus tard)"; then
  ouvert "$TS_IP" 443 && r=ok || r=ko
  attendu "après la politique : 443 toujours ouvert" "$r"
else
  SKIPPED+=("politique du tailnet vers plakar-ui")
fi

# ── 13 ─────────────────────────────────────────────────────────────────────
stage "Identité hors de la liste refusée"
say "On retire ton identité de la liste, le temps d'un essai. Sur le LXC :"
note "    sed -i \"s/^PLAKAR_UI_UTILISATEURS=.*/PLAKAR_UI_UTILISATEURS='personne@example.invalid'/\" .env"
note "    docker compose up -d plakar-ui"
pause "Entrée une fois plakar-ui redémarré"
code=$(code_https "https://${PLAKAR_UI_HOTE}/")
[[ "$code" == 403 ]] && r=ok || r=ko
attendu "identité hors liste : 403 (reçu : ${code:-rien})" "$r"
say "Remets ton identité, sur le LXC :"
note "    sed -i \"s/^PLAKAR_UI_UTILISATEURS=.*/PLAKAR_UI_UTILISATEURS='${PLAKAR_UI_UTILISATEURS}'/\" .env"
note "    docker compose up -d plakar-ui"
pause "Entrée une fois plakar-ui redémarré"
code=$(code_https "https://${PLAKAR_UI_HOTE}/")
[[ "$code" == 200 ]] && r=ok || r=ko
attendu "identité rétablie : 200 (reçu : ${code:-rien})" "$r"
pause "Entrée pour le résumé"

finish
say "Reste à cocher les cases du ticket .scratch/plakar-ui/issues/09-deploiement-unraid.md."
}

run_wizard "$@"; exit
